CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 INT NOT NULL DEFAULT 0, c1 NUMERIC DEFAULT 'd', c2 TEXT NOT NULL DEFAULT 0, c3 INT);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES(0, NULL, '', x'8b2fa0a7');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES(0, NULL, x'', x'');
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 TEXT COLLATE NOCASE, c1, c2 TEXT, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(NULL, NULL, 3, 6);
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(x'0724a620a624', ' pad ', NULL, 3);
SELECT length('xi'), upper('xi'), lower('xi'), substr('xi', 1, 3), instr('xi', 'upsilon'), replace('xi', 'é', 'XY'), trim('xi'), ltrim('xi', 'ab'), hex('xi'), quote('xi'), unicode('xi'), 'xi' LIKE '%a_', 'xi' GLOB '*', char(73, 589), 'xi' || 'upsilon', 'xi' < 'upsilon', 'xi' = 'upsilon' COLLATE NOCASE;
SELECT length('phi'), upper('phi'), lower('phi'), substr('phi', 2, 3), instr('phi', 'tau'), replace('phi', 'é', 'XY'), trim('phi'), ltrim('phi', 'ab'), hex('phi'), quote('phi'), unicode('phi'), 'phi' LIKE '_', 'phi' GLOB '*[a-m]*', char(65, 489), 'phi' || 'tau', 'phi' < 'tau', 'phi' = 'tau' COLLATE NOCASE;
SELECT length('upsilon'), upper('upsilon'), lower('upsilon'), substr('upsilon', 4, 2), instr('upsilon', 'gamma'), replace('upsilon', 'é', '_'), trim('upsilon'), ltrim('upsilon', 'ab'), hex('upsilon'), quote('upsilon'), unicode('upsilon'), 'upsilon' LIKE 'A%', 'upsilon' GLOB 'a*', char(65, 443), 'upsilon' || 'gamma', 'upsilon' < 'gamma', 'upsilon' = 'gamma' COLLATE NOCASE;
SELECT length('it''s'), upper('it''s'), lower('it''s'), substr('it''s', -3, 5), instr('it''s', 'upsilon'), replace('it''s', 'a', 'XY'), trim('it''s'), ltrim('it''s', 'ab'), hex('it''s'), quote('it''s'), unicode('it''s'), 'it''s' LIKE 'A%', 'it''s' GLOB '*[a-m]*', char(65, 814), 'it''s' || 'upsilon', 'it''s' < 'upsilon', 'it''s' = 'upsilon' COLLATE NOCASE;
SELECT length('gamma'), upper('gamma'), lower('gamma'), substr('gamma', -1, 4), instr('gamma', 'upsilon'), replace('gamma', 'a', 'XY'), trim('gamma'), ltrim('gamma', 'ab'), hex('gamma'), quote('gamma'), unicode('gamma'), 'gamma' LIKE '%é%', 'gamma' GLOB '*', char(75, 899), 'gamma' || 'upsilon', 'gamma' < 'upsilon', 'gamma' = 'upsilon' COLLATE NOCASE;
SELECT length('a%b'), upper('a%b'), lower('a%b'), substr('a%b', -1, 5), instr('a%b', 'gamma'), replace('a%b', 'é', 'XY'), trim('a%b'), ltrim('a%b', 'ab'), hex('a%b'), quote('a%b'), unicode('a%b'), 'a%b' LIKE 'A%', 'a%b' GLOB '?', char(82, 839), 'a%b' || 'gamma', 'a%b' < 'gamma', 'a%b' = 'gamma' COLLATE NOCASE;
SELECT length('alpha'), upper('alpha'), lower('alpha'), substr('alpha', -2, 1), instr('alpha', 'NULL'), replace('alpha', 'e', '_'), trim('alpha'), ltrim('alpha', 'ab'), hex('alpha'), quote('alpha'), unicode('alpha'), 'alpha' LIKE '%', 'alpha' GLOB '*[a-m]*', char(84, 951), 'alpha' || 'NULL', 'alpha' < 'NULL', 'alpha' = 'NULL' COLLATE NOCASE;
SELECT a.id, b.id, a.c0, b.c0 FROM t0 a LEFT OUTER JOIN t1 b ON b.ref = a.id ORDER BY 1, 2 LIMIT 37;
SELECT count(*) FROM t0 a JOIN t0 b USING(id) WHERE a.CASE WHEN 405 THEN ' pad ' ELSE NOT c3 END;
SELECT count(*), count(ref), sum(ref), total(ref), avg(ref), min(ref), max(ref), count(DISTINCT ref) FROM t1 WHERE ref;
SELECT ref, count(*), group_concat(id, ';') FROM (SELECT * FROM t1 ORDER BY id) GROUP BY ref HAVING count(*) > 0 ORDER BY ref;
UPDATE t1 SET c0 = nullif(x'', c0) IN (c0, 'Lambda', NULL);
DELETE FROM t1 WHERE id % 3 = 0;
SELECT * FROM t1 ORDER BY id DESC, c0, c1, c2, ref;
